type correctionThenLoader[Q orm.Loadable] struct {
	CreatedByMember func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Household       func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Purchase        func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Journal         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	PurchaseItem    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildCorrectionThenLoader[Q orm.Loadable]() correctionThenLoader[Q] {
	type CreatedByMemberLoadInterface interface {
		LoadCreatedByMember(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type HouseholdLoadInterface interface {
		LoadHousehold(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PurchaseLoadInterface interface {
		LoadPurchase(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type JournalLoadInterface interface {
		LoadJournal(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type PurchaseItemLoadInterface interface {
		LoadPurchaseItem(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return correctionThenLoader[Q]{
		CreatedByMember: thenLoadBuilder[Q](
			"CreatedByMember",
			func(ctx context.Context, exec bob.Executor, retrieved CreatedByMemberLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCreatedByMember(ctx, exec, mods...)
			},
		),
		Household: thenLoadBuilder[Q](
			"Household",
			func(ctx context.Context, exec bob.Executor, retrieved HouseholdLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadHousehold(ctx, exec, mods...)
			},
		),
		Purchase: thenLoadBuilder[Q](
			"Purchase",
			func(ctx context.Context, exec bob.Executor, retrieved PurchaseLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadPurchase(ctx, exec, mods...)
			},
		),
		Journal: thenLoadBuilder[Q](
			"Journal",
			func(ctx context.Context, exec bob.Executor, retrieved JournalLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadJournal(ctx, exec, mods...)
			},
		),
		PurchaseItem: thenLoadBuilder[Q](
			"PurchaseItem",
			func(ctx context.Context, exec bob.Executor, retrieved PurchaseItemLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadPurchaseItem(ctx, exec, mods...)
			},
		),
	}
}

// LoadCreatedByMember loads the correction's CreatedByMember into the .R struct
func (o *Correction) LoadCreatedByMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.CreatedByMember = nil
	o.R.Loaded.CreatedByMember = false

	related, err := o.CreatedByMember(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.CreatedByCorrections = CorrectionSlice{o}

	o.R.CreatedByMember = related
	o.R.Loaded.CreatedByMember = true
	return nil
}

// LoadCreatedByMember loads the correction's CreatedByMember into the .R struct
func (os CorrectionSlice) LoadCreatedByMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.CreatedByMember(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.CreatedByMember = nil
		o.R.Loaded.CreatedByMember = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	correctionByKey := make(map[uuid.UUID][]*Correction, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		correctionByKey[o.CreatedBy] = append(correctionByKey[o.CreatedBy], o)
	}

	for _, rel := range members {

		owners, ok := correctionByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.CreatedByMember != nil {
				continue
			}

			rel.R.CreatedByCorrections = append(rel.R.CreatedByCorrections, o)

			o.R.CreatedByMember = rel

		}
	}

	return nil
}

