// LoadPurchase loads the correction's Purchase into the .R struct
func (os CorrectionSlice) LoadPurchase(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	purchases, err := os.Purchase(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Purchase = nil
		o.R.Loaded.Purchase = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range purchases {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.PurchaseID == rel.ID) {
				continue
			}

			rel.R.Corrections = append(rel.R.Corrections, o)

			o.R.Purchase = rel
			break
		}
	}

	return nil
}

